import{_ as n,l as i,o as e,c as l,v as r,p as s,x as t,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"风险调整比率的抽样误差","description":"","frontmatter":{"title":"风险调整比率的抽样误差","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ratio-sampling-error.md","filePath":"quant/ratio-sampling-error.md","lastUpdated":1789023840000}'),E={name:"quant/ratio-sampling-error.md"};function m(c,a,A,u,_,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="风险调整比率的抽样误差" tabindex="-1">风险调整比率的抽样误差 <a class="header-anchor" href="#风险调整比率的抽样误差" aria-label="Permalink to &quot;风险调整比率的抽样误差&quot;">​</a></h1><div class="epigraph"><p>夏普是均值除以标准差；均值在短样本上几乎估不准，于是小数点后两位的 IR 排序往往没有统计内容。</p><footer>—— Merton, On Estimating the Expected Return on the Market, Journal of Financial Economics, 1980；夏普的抽样理论见 Lo, Financial Analysts Journal, 2002</footer></div><p><a href="/quant/trade-level-attribution">上一课</a>把 P&amp;L 拆清了。本课的缺口是<strong>清过的账仍然是短样本</strong>：<a href="/quant/ir-sharpe">IR/Sharpe</a> 的点估计方差很大。Merton（1980）说明：估计预期收益需要极长的日历时间，提高采样频率帮不上均值。Lo（2002）给出夏普在序列相关下的分布。Jobson–Korkie 讨论两基金夏普之差的检验。<a href="/quant/deflated-sharpe">放气夏普</a> 与 <a href="/quant/probabilistic-sharpe">概率夏普</a> 把选择偏差叠加上去。本课收口业绩单元：比率是估计量，不是标签。下一课程从 <a href="/quant/matching-engine-arch">撮合引擎</a> 起，解释这些收益里的成交在系统里如何被排程——没有引擎时间戳，连「一笔交易」的定义都会漂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>年化夏普 \\(\\hat{\\mathrm{SR}}=\\bar x/s_x\\sqrt{q}\\)。\\(\\bar x\\) 的误差是 \\(\\sigma/\\sqrt{T_{\\mathrm{年}}}\\) 量级，与日内格子密度几乎无关。三年月频、夏普 1.0，置信区间可以跨过 0。Sortino 只用下行观测，更噪。问题是比较：基金 A 夏普 1.1、B 夏普 0.9，在合理 \\(T\\) 与相关下经常不可区分。把地图上每一类策略按样本夏普排名，再据此加杠杆，是用噪声做风险预算。</p><p>与费用、流：扣费与 MWR 改变的是点估计的中心，不缩小抽样方差。技能若有，仍要过「估计误差 + 选择偏差」两关。</p><h3 id="相关与重叠" tabindex="-1">相关与重叠 <a class="header-anchor" href="#相关与重叠" aria-label="Permalink to &quot;相关与重叠&quot;">​</a></h3><p>多只基金暴露同一 ARP 时，夏普之差的方差不含「独立样本」那么小。策略桶之间的相关升（危机）让「分散的 IR」不可加。长地平重叠收益的标准误见主干重叠课，此处只提醒：用同一段市场路径评价所有产品，有效 \\(T\\) 是一段牛熊，不是产品个数。</p><p><span class="marginnote">提高日频只改善 \\(\\sigma\\) 的估计，几乎不改善 \\(\\mu\\)。把日频夏普报成三位小数，是对 Merton 1980 的忽视。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告：点估计 + Lo 调整的标准误或置信区间；PSR/DSR 对 \\(N\\) 次试验。比较：Jobson–Korkie 或 bootstrap 两样本。预注册评价窗口。杠杆前先看区间是否不含零，而不是看点估计是否大于 1。对短波动等非对称策略，夏普尤其误导，应并报缺口月。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>比率的分子是漂移，分母是波动。扩散里，漂移的信息随日历时间累积，波动的信息随采样累积。于是「高夏普」在短样本上大量是运气。选择偏差再把运气的上分位当成产品。业绩单元能做的是把会计做对、把误差报出来；不能把噪声变成技能。</p>',13)),(e(),s(p,null,{default:t(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Px%5B%22%E5%B7%B2%E5%AF%B9%E9%BD%90%E7%9A%84%E5%87%80%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20SR%5B%22%E5%A4%8F%E6%99%AE%20IR%20Sortino%22%5D%0A%20%20SR%20--%3E%20SE%5B%22%E6%8A%BD%E6%A0%B7%E8%AF%AF%E5%B7%AE%20%E9%9A%8F%E6%97%A5%E5%8E%86%20T%22%5D%0A%20%20N%5B%22%E8%AF%95%E9%AA%8C%E6%AC%A1%E6%95%B0%22%5D%20--%3E%20DSR%5B%22%E6%94%BE%E6%B0%94%22%5D%0A%20%20SE%20--%3E%20Dec%5B%22%E8%83%BD%E5%90%A6%E5%8C%BA%E5%88%86%E4%B8%A4%E5%8F%AA%E4%BA%A7%E5%93%81%22%5D%0A%20%20DSR%20--%3E%20Dec%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给「最低可接受夏普」的营销数字。非正态、跳、制度断点让渐近公式偏乐观。要解释成交为何存在、时间戳如何定义，必须进入交易所技术：从撮合引擎架构开始。组合与策略进阶到此结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>夏普/IR 是高方差估计量；均值几乎只随日历时间变准。</li><li>产品排序须带标准误与试验次数，不能靠点估计加杠杆。</li><li>会计对齐之后，剩下的是噪声与真正技能的分离。</li><li>出处：Merton, <em>JFE</em>, 1980；Lo, <em>FAJ</em>, 2002；Bailey and López de Prado 放气夏普。下一课：<a href="/quant/matching-engine-arch">撮合引擎架构</a>。</li></ul>',4))])}const b=n(E,[["render",m]]);export{B as __pageData,b as default};
